import { setCanonicalStatus, updateCanonicalStatus, deleteCanonicalStatus } from './canonical-status-fixture.js';
// AI-generated by scale-codex-4. Real disposable Firestore; scaled pages/budget test ownership, not cloud capacity.
import { afterEach, beforeEach, expect, test } from 'vitest';
import { readCurrentStateRefresh } from '../src/view/current-state-progress-reader.js';
import { inProject } from '../src/firestore.js';
import { configureCurrentState, currentStateStats, readCurrentState, stopCurrentState, type CurrentStateAnswer } from '../src/view/current-state.js';
import { resetEmulator } from './helpers.js';

const A = 'a'.repeat(64), B = 'b'.repeat(64), C = 'c'.repeat(64);
let clock = 0, restore = () => {};
beforeEach(async () => {
  stopCurrentState(); await resetEmulator(); clock = 0;
  restore = configureCurrentState({ maxProjects: 1, currentBytes: 0, pageSize: 2, clock: () => clock });
});
afterEach(() => { restore(); stopCurrentState(); });
const read = (project: string, cursor?: string, viewer = 'viewer') => inProject(project, () => readCurrentState(viewer, false, cursor, 100_000));
async function fixture(project: string) {
  await inProject(project, async () => {
    for (let n = 0; n < 7; n++) await setCanonicalStatus(`row-${n}`,{ runId: null, runEndedAt: null,
      agent: { name: `Agent ${n}`, ownerProfileId: 'owner', connectionEpoch: 0, revokedAt: null, focus: null, personaText: '' } } as never);
  });
}
async function drain(project: string, first: CurrentStateAnswer, viewer = 'viewer') {
  const rows = new Map(first.rows.map(row => [row.id, row])); let answer = first, pages = 1;
  while (answer.more && pages < 10) {
    answer = await read(project, answer.cursor, viewer); pages++;
    for (const row of answer.rows) rows.set(row.id, row);
  }
  expect(answer.complete).toBe(true); expect(pages).toBe(4);
  expect([...rows.keys()].sort()).toEqual(Array.from({ length: 7 }, (_, n) => `row-${n}`));
  return { answer, rows };
}

test('equal-size no-victim serial bootstrap owns one collection read; completion releases it and next poll sees a write behind the cursor', async () => {
  await fixture(A); await fixture(B); await drain(A, await read(A));
  const before = currentStateStats(), first = await read(B);
  expect(first.more).toBe(true);
  await inProject(B, () => updateCanonicalStatus('row-0',{ 'agent.focus': { text: 'after pin', updatedAt: 1 } }));
  const result = await drain(B, first);
  const after = currentStateStats();
  expect(after.oneShots - before.oneShots).toBe(1); expect(after.oneShotDocs - before.oneShotDocs).toBe(7);
  expect(after).toMatchObject({ cachedProjects: 1, ownedChains: 0, ownedSnapshots: 0, ownedBytes: 0 });
  expect(result.answer.watermark).toBe(first.watermark);
  const next = await read(B, result.answer.cursor);
  expect(next.complete).toBe(true);
  expect(next.rows.find(row => row.id === 'row-0')).toMatchObject({ focus: { text: 'after pin' } });
  expect(currentStateStats().oneShots - before.oneShots).toBe(2);
});

test('four overlapping viewers retain independent immutable inputs and completing cursors', async () => {
  await fixture(B); configureCurrentState({ maxProjects: 0 });
  let release!: () => void, entered!: () => void;
  const held = new Promise<void>(resolve => { release = resolve; });
  const started = new Promise<void>(resolve => { entered = resolve; });
  configureCurrentState({ refresh: async previous => { entered(); await held; return readCurrentStateRefresh(previous); } });
  const viewers = ['one', 'two', 'three', 'four'];
  const offered = viewers.map(viewer => read(B, undefined, viewer));
  await started; release();
  const first = await Promise.all(offered);
  expect(new Set(first.map(answer => answer.cursor)).size).toBe(4);
  expect(currentStateStats()).toMatchObject({ oneShots: 4, ownedChains: 4, ownedSnapshots: 4 });
  const charged = currentStateStats().ownedBytes;
  await drain(B, first[0]!, viewers[0]);
  expect(currentStateStats()).toMatchObject({ ownedChains: 3, ownedSnapshots: 3 });
  expect(currentStateStats().ownedBytes).toBeLessThan(charged);
  for (let n = 1; n < first.length; n++) await drain(B, first[n]!, viewers[n]);
  expect(currentStateStats()).toMatchObject({ oneShots: 4, ownedChains: 0, ownedSnapshots: 0, ownedBytes: 0 });
});

test('replay, foreign epoch, wrong viewer and aged ownership resume from the same floor with counted fresh reads', async () => {
  await fixture(B); configureCurrentState({ maxProjects: 0 });
  const first = await read(B), second = await read(B, first.cursor);
  const before = currentStateStats().oneShots;
  const replay = await read(B, first.cursor);
  expect(replay.rows.map(row => row.id)).toEqual(second.rows.map(row => row.id));
  const otherViewer = await read(B, second.cursor, 'someone-else');
  expect(otherViewer.watermark! >= first.watermark!).toBe(true);
  const foreign = second.cursor.replace(/:[0-9a-f]{32}$/, ':' + '0'.repeat(32));
  const moved = await read(B, foreign); expect(moved.watermark! >= first.watermark!).toBe(true);
  const third = await read(B, second.cursor); expect(third.more).toBe(true);
  clock += 10001;
  const aged = await read(B, third.cursor); expect(aged).toMatchObject({ complete: true, notReady: false });
  expect(aged.watermark! >= first.watermark!).toBe(true);
  expect(currentStateStats().oneShots - before).toBe(4);
  const fresh = await read(B); expect(fresh.notReady).toBe(false);
  expect(currentStateStats().ownedMiss).toBe(4);
});

test('byte-budget eviction is counted and resumes with a fresh read; an oversized input still completes by fresh reads', async () => {
  await fixture(B); await fixture(C); configureCurrentState({ maxProjects: 0 });
  const first = await read(B), budget = currentStateStats().ownedBytes;
  configureCurrentState({ ownedBytes: budget });
  const other = await read(C);
  expect(currentStateStats()).toMatchObject({ ownedChains: 1, ownedEvictions: 1 });
  expect(currentStateStats().ownedBytes).toBeLessThanOrEqual(budget);
  const beforeRecovery = currentStateStats().oneShots;
  let recovered = await read(B, first.cursor);
  expect(recovered.watermark! >= first.watermark!).toBe(true);
  while (recovered.more) recovered = await read(B, recovered.cursor);
  expect(recovered.complete).toBe(true);
  expect(currentStateStats().oneShots - beforeRecovery).toBe(1);
  expect(currentStateStats().ownedMiss).toBe(1);
  await drain(C, other);
  configureCurrentState({ ownedBytes: 1 });
  const before = currentStateStats().oneShots;
  await drain(B, await read(B));
  expect(currentStateStats()).toMatchObject({ ownedChains: 0, ownedBytes: 0, ownedBypass: 3 });
  expect(currentStateStats().oneShots - before).toBe(4);
});

test('losing all process ownership resumes an existing cursor with one fresh query instead of restarting page one', async () => {
  await fixture(B); configureCurrentState({ maxProjects: 0 });
  const first = await read(B); stopCurrentState();  // simulate another process with no ownership or listeners
  let answer = await read(B, first.cursor), pages = 2;
  const ids = [...first.rows, ...answer.rows].map(row => row.id);
  expect(answer.rows.map(row => row.id)).toEqual(['row-2', 'row-3']);
  expect(answer.watermark! >= first.watermark!).toBe(true);
  while (answer.more) { answer = await read(B, answer.cursor); ids.push(...answer.rows.map(row => row.id)); pages++; }
  expect(answer.complete).toBe(true); expect(pages).toBe(4);
  expect(ids).toEqual(Array.from({ length: 7 }, (_, n) => `row-${n}`));
  expect(currentStateStats()).toMatchObject({ oneShots: 1, ownedMiss: 1, ownedChains: 0, ownedBytes: 0 });
});

test('cold recovery replays deletion at its original commit revision without regressing a held floor', async () => {
  configureCurrentState({ maxProjects: 0, pageSize: 10 }); await fixture(B);
  const first = await read(B);
  await inProject(B, () => deleteCanonicalStatus('row-0'));
  const changed = await read(B, first.cursor);
  expect(changed.rows).toContainEqual(expect.objectContaining({ id: 'row-0', removed: true }));
  stopCurrentState();
  const cold = await read(B, first.cursor);
  expect(cold.rows).toEqual(changed.rows);
  expect(cold.watermark! >= changed.watermark!).toBe(true);
});
